335	    @Transactional
336	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
337	            String corrects) {
338	        RollupService.Snapshot before = rollup.snapshot(sheetId);
339	        Person person = people.findByIdAndSheetId(personId, sheetId)
340	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
341	        LocalDate dated = dateOr(sheetId, date);
342	        periods.requireOpen(sheetId, dated);
343	        person.requireClaimable(dated);
344	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
345	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
346	        claim.setCorrects(corrects);
347	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
348	        // Due by its date plus the terms of its person's grade on that date, fixed from now on.
349	        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated)));
350	        claim.setListed(sheets.nextListed(sheetId));
351	        Claim saved = claims.saveAndFlush(claim);
352	        log(sheetId, user, person, saved);
353	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
354	        rollup.recordChanges(sheetId, user, before);
355	        return saved;
356	    }
