358	    @Transactional
359	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
360	            String corrects) {
361	        RollupService.Snapshot before = rollup.snapshot(sheetId);
362	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
363	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
364	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
365	        if (claim.getStatus() != ClaimStatus.DRAFT) {
366	            throw new ClaimNotEditableException(id, claim.getStatus());
367	        }
368	        LocalDate dated = dateOr(sheetId, date);
369	        // Neither out of nor into a closed period.
370	        periods.requireOpen(sheetId, claim.getDate(), dated);
371	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
372	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
373	                .requireClaimable(dated);
374	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
375	        claim.setAmount(amount);
376	        claim.setCorrects(corrects);
377	        claim.setDate(dated);
378	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
379	        claim.setNote(noteOf(note));
380	        Claim saved = claims.saveAndFlush(claim);
381	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
382	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
383	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
384	        rollup.recordChanges(sheetId, user, before);
385	        return saved;
386	    }
