388	    /**
389	     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
390	     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
391	     */
392	    @Transactional
393	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
394	        Claim claim = claims.findForUpdate(id, sheetId)
395	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
396	        if (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING) {
397	            throw new ClaimStatusException(id, claim.getStatus(), status);
398	        }
399	        // The sheet's permission matrix decides which roles may open, settle or void.
400	        String action = switch (status) {
401	            case OPEN -> "open";
402	            case SETTLED -> "settle";
403	            case VOID -> "void";
404	            case DRAFT, PENDING -> throw new ClaimStatusException(id, claim.getStatus(), status);
405	        };
406	        if (!roles.may(sheetId, user, action)) {
407	            throw new ClaimActionForbiddenException(id, user, action);
408	        }
409	        periods.requireOpen(sheetId, claim.getDate());
410	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
411	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
412	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
413	        }
414	        // Four eyes: whoever opened a claim cannot also settle it.
415	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
416	            throw new ClaimSettledByOpenerException(id, user);
417	        }
418	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
419	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
420	        if (status == ClaimStatus.SETTLED) {
421	            requireProof(sheetId, person, claim);
422	        }
423	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
424	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
425	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
426	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
427	            BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
428	            if (limit != null && due != null && due.compareTo(limit) > 0) {
429	                status = ClaimStatus.PENDING;
430	            }
431	        }
432	        RollupService.Snapshot before = rollup.snapshot(sheetId);
433	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim) : "";
434	        claim.setStatus(status);
435	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
436	        String number = claim.getNumber();
437	        if (status == ClaimStatus.OPEN) {
438	            number = nextNumber(sheetId, claim.getDate());
439	            claim.setNumber(number);
440	            claim.setOpenedBy(user);
441	        }
442	        Claim saved = claims.saveAndFlush(claim);
443	        log(sheetId, user, person, saved);
444	        String event = switch (status) {
445	            case OPEN -> "CLAIM_OPENED";
446	            case PENDING -> "CLAIM_PENDING";
447	            case SETTLED -> "CLAIM_SETTLED";
448	            case VOID -> "CLAIM_VOIDED";
449	            case DRAFT -> throw new IllegalStateException();
450	        };
451	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
452	        rollup.recordChanges(sheetId, user, before);
453	        return saved;
454	    }
