456	    /**
457	     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
458	     * its live figure.
459	     */
460	    @Transactional
461	    public Claim approve(String sheetId, String user, Long id) {
462	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
463	        if (user.equals(claim.getOpenedBy())) {
464	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
465	        }
466	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
467	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
468	        requireProof(sheetId, person, claim);
469	        RollupService.Snapshot before = rollup.snapshot(sheetId);
470	        String due = settle(sheetId, person, claim);
471	        claim.setStatus(ClaimStatus.SETTLED);
472	        Claim saved = claims.saveAndFlush(claim);
473	        log(sheetId, user, person, saved);
474	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
475	        rollup.recordChanges(sheetId, user, before);
476	        return saved;
477	    }
