498	    /**
499	     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
500	     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
501	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
502	     * retired before its date, or a user whose role may not reassign.
503	     */
504	    @Transactional
505	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
506	        Claim claim = claims.findForUpdate(id, sheetId)
507	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
508	        if (!roles.may(sheetId, user, "reassign")) {
509	            throw new ClaimReassignForbiddenException(id, user);
510	        }
511	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
512	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
513	        }
514	        if (claim.getPersonId().equals(toPersonId)) {
515	            throw new ClaimReassignException(id, "it is already that person's");
516	        }
517	        periods.requireOpen(sheetId, claim.getDate());
518	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
519	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
520	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
521	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
522	        to.requireClaimable(claim.getDate());
523	        RollupService.Snapshot before = rollup.snapshot(sheetId);
524	        claim.setPersonId(to.getId());
525	        claim.setStated(false, null);
526	        claim.setListed(sheets.nextListed(sheetId));
527	        Claim saved = claims.saveAndFlush(claim);
528	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
529	                + " from=" + from.getName() + " to=" + to.getName());
530	        rollup.recordChanges(sheetId, user, before);
531	        return saved;
532	    }
