534	    /**
535	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
536	     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
537	     * date not after today, or a closed period.
538	     */
539	    @Transactional
540	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
541	        Claim claim = claims.findForUpdate(id, sheetId)
542	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
543	        if (claim.getStatus() != ClaimStatus.OPEN) {
544	            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
545	        }
546	        LocalDate today = sheets.today(sheetId);
547	        if (until == null || !until.isAfter(today)) {
548	            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
549	        }
550	        periods.requireOpen(sheetId, claim.getDate());
551	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
552	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
553	        RollupService.Snapshot before = rollup.snapshot(sheetId);
554	        claim.setDeferredUntil(until);
555	        Claim saved = claims.saveAndFlush(claim);
556	        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
557	                + " until=" + until);
558	        rollup.recordChanges(sheetId, user, before);
559	        return saved;
560	    }
