562	    /**
563	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
564	     * bound by no statement (today's rates, grades and floor, with its late charge as of today). Refused for any other
565	     * status, a closed period, or a user not a steward.
566	     */
567	    @Transactional
568	    public Claim resettle(String sheetId, String user, Long id) {
569	        Claim claim = claims.findForUpdate(id, sheetId)
570	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
571	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
572	            throw new ClaimResettleForbiddenException(id, user);
573	        }
574	        if (claim.getStatus() != ClaimStatus.SETTLED) {
575	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
576	        }
577	        periods.requireOpen(sheetId, claim.getDate());
578	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
579	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
580	        RollupService.Snapshot before = rollup.snapshot(sheetId);
581	        String old = shownDue(sheetId, person, claim);
582	        BigDecimal figure = dueOf(sheetId, person, claim);
583	        claim.setSettledDue(settings.get(sheetId).withLateCharge(figure, !claim.isCorrection(), claim.getDueBy(),
584	                claim.getDate()));
585	        Claim saved = claims.saveAndFlush(claim);
586	        log(sheetId, user, person, saved);
587	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
588	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
589	        rollup.recordChanges(sheetId, user, before);
590	        return saved;
591	    }
