593	    /**
594	     * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED or VOID claim, or a closed period.
595	     */
596	    @Transactional
597	    public Claim addProof(String sheetId, String user, Long id) {
598	        Claim claim = claims.findForUpdate(id, sheetId)
599	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
600	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
601	            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
602	        }
603	        periods.requireOpen(sheetId, claim.getDate());
604	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
605	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
606	        claim.addProof();
607	        Claim saved = claims.saveAndFlush(claim);
608	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
609	                + " proofs=" + saved.getProofs());
610	        return saved;
611	    }
