613	    /**
614	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date cannot be
615	     * settled or approved while it has no proof; refused then. A due of n/a is within any threshold.
616	     */
617	    private void requireProof(String sheetId, Person person, Claim claim) {
618	        BigDecimal threshold = settings.get(sheetId).proofThresholdOn(claim.getDate());
619	        if (threshold == null || claim.getProofs() > 0) {
620	            return;
621	        }
622	        BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
623	        if (due != null && due.compareTo(threshold) > 0) {
624	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
625	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
626	        }
627	    }
628	
629	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
630	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
631	        Claim claim = claims.findForUpdate(id, sheetId)
632	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
633	        if (claim.getStatus() != ClaimStatus.PENDING) {
634	            throw new ClaimStatusException(id, claim.getStatus(), to);
635	        }
636	        periods.requireOpen(sheetId, claim.getDate());
637	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
638	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
639	        }
640	        return claim;
641	    }
642	
643	    /**
644	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
645	     * the rate on the claim's date) with its late charge frozen in; with no figure it stays live. Gives the due at the
646	     * end of its audit record.
647	     */
648	    private String settle(String sheetId, Person person, Claim claim) {
649	        BigDecimal figure = figureOf(sheetId, person, claim);
650	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
651	                : figure.add(settings.get(sheetId).lateCharge(figure, claim.getDueBy(), claim.getDate()));
652	        claim.setSettledDue(settledDue);
653	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
654	    }
655	
656	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
657	    private void log(String sheetId, String user, Person person, Claim claim) {
658	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
659	                shownDue(sheetId, person, claim)));
660	    }
661	
662	    /**
663	     * The claim's due as shown: the one fixed when it was settled, else its figure with its late charge on top; two
664	     * decimals, or n/a.
665	     */
666	    private String shownDue(String sheetId, Person person, Claim claim) {
667	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
668	                : withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
669	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
670	    }
671	
672	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
673	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
674	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
675	    }
676	
677	    /**
678	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
679	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
680	     * for any other claim.
681	     */
682	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
683	        if (amount.signum() >= 0) {
684	            if (corrects != null) {
685	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
686	            }
687	            return null;
688	        }
689	        if (corrects == null) {
690	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
691	        }
692	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
693	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
694	                .map(Claim::getDate)
695	                .orElseThrow(() -> new ClaimCorrectionException(
696	                        "Claim " + corrects + " is not a settled claim of the same person"));
697	    }
698	
699	    /**
700	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
701	     * date has the claim round, raised to the sheet's floor on its date unless it is a correction; null (n/a) with no rate.
702	     */
703	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
704	        Sheet sheet = settings.get(sheetId);
705	        BigDecimal due = rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
706	                .map(Rate::getPct)
707	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
708	                .orElse(null);
709	        return claim.isCorrection() ? due : sheet.floored(due, claim.getDate());
710	    }
711	
712	    /**
713	     * The due with the late charge of an OPEN or PENDING claim overdue on the sheet's today added on top (none on a
714	     * correction, nor on a claim deferred on the sheet's today); null (n/a) stays null.
715	     */
716	    private BigDecimal withLateCharge(String sheetId, Claim claim, BigDecimal due) {
717	        Sheet sheet = settings.get(sheetId);
718	        return sheet.withLateCharge(due, claim.getStatus().isOpen() && !claim.isCorrection()
719	                && !claim.isDeferredOn(sheet.getToday()), claim.getDueBy(), claim.getDate());
720	    }
721	
722	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
723	    private static String record(String event, String user, Person person, Claim claim) {
724	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
725	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
726	                + " date=" + claim.getDate();
727	    }
728	
729	    /** The claim's number at the end of an audit record, or nothing when it has none. */
730	    private static String numberOf(String number) {
731	        return number == null ? "" : " number=" + number;
732	    }
733	
734	    /**
735	     * The number a claim dated on the date gets when opened: while the sheet numbers by period, the next in its
736	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
737	     */
738	    private String nextNumber(String sheetId, LocalDate date) {
739	        if (settings.get(sheetId).numbersByPeriod()) {
740	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
741	        }
742	        return String.valueOf(sheets.nextClaimNumber(sheetId));
743	    }
744	
745	    private LocalDate dateOr(String sheetId, LocalDate date) {
746	        return date != null ? date : sheets.today(sheetId);
747	    }
748	
749	    private static String noteOf(String note) {
750	        return note == null ? "" : note.trim();
751	    }
752	}
