777	/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
778	@RestController
779	@RequestMapping("/api/sheets/{sheetId}")
780	@Validated
781	public class ClaimController {
782	
783	    /**
784	     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
785	     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
786	     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
787	     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
788	     * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
789	     * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
790	     * it has.
791	     */
792	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
793	            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
794	            LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
795	            int proofs) {
796	
797	        static ClaimView of(Claim claim, List<ClaimLog> log) {
798	            return new ClaimView(claim.getId(), claim.getPersonId(),
799	                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
800	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
801	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
802	                    claim.getOpenedBy(), claim.isStated(),
803	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
804	                    claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
805	                    log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
806	                    claim.getProofs());
807	        }
808	    }
809	
810	    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and its due then (or n/a). */
811	    public record ClaimLogView(ClaimStatus status, String by, LocalDate date, String due) {
812	
813	        static ClaimLogView of(ClaimLog line) {
814	            return new ClaimLogView(line.getStatus(), line.getBy(), line.getDate(), line.getDue());
815	        }
816	    }
817	
818	    /**
819	     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
820	     * number of the claim a correction corrects, blank for any other claim.
821	     */
822	    public record ClaimRequest(
823	            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
824	            LocalDate date,
825	            @Size(max = 1000) String note,
826	            @Size(max = 255) String corrects) {
827	
828	        BigDecimal amountValue() {
829	            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
830	        }
831	
832	        String correctsValue() {
833	            if (corrects == null || corrects.isBlank()) {
834	                return null;
835	            }
836	            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
837	            String trimmed = corrects.trim();
838	            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
839	        }
840	    }
841	
842	    /** The ids of the claims selected to open together. */
843	    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
844	    }
845	
846	    /** The ids of the claims selected to settle together. */
847	    public record BulkSettleRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
848	    }
849	
850	    /** Lines of name,amount,date,note to add as DRAFT claims. */
851	    public record PasteRequest(@NotNull @Size(max = 1000000) String text) {
852	    }
853	
854	    /** How many claims a paste added. */
855	    public record PasteResult(int added) {
856	    }
857	
858	    private final ClaimService service;
859	    private final BulkOpenService bulkOpen;
860	    private final BulkSettleService bulkSettle;
861	    private final PasteClaimsService paste;
