866	        this.bulkOpen = bulkOpen;
867	        this.bulkSettle = bulkSettle;
868	        this.paste = paste;
869	    }
870	
871	    /** All the sheet's claims, newest first. */
872	    @GetMapping("/claims")
873	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
874	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
875	        Map<Long, List<ClaimLog>> logs = service.logs(sheetId.trim());
876	        return service.list(sheetId.trim()).stream()
877	                .map(claim -> ClaimView.of(claim, logs.getOrDefault(claim.getId(), List.of())))
878	                .toList();
