890	
891	    /** Add a DRAFT claim per pasted line, in order; refused as a whole when any line would be. */
892	    @PostMapping("/claims/paste")
893	    public PasteResult paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
894	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
895	            @RequestBody @Valid PasteRequest request) {
896	        return new PasteResult(paste.paste(sheetId.trim(), user.trim(), request.text()));
897	    }
898	
899	    /** Edit a DRAFT claim; refused for any other status. */
900	    @PutMapping("/claims/{id}")
901	    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
902	            @PathVariable Long id,
903	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
904	            @RequestBody @Valid ClaimRequest request) {
905	        return view(service.update(sheetId.trim(), user.trim(), id, request.amountValue(), request.date(),
906	                request.note(), request.correctsValue()));
907	    }
908	
909	    /** Open a DRAFT claim. */
910	    @PostMapping("/claims/{id}/open")
911	    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
912	            @PathVariable Long id,
913	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
914	        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.OPEN));
915	    }
916	
917	    /** Open the selected claims in list order; each one that cannot be opened is left as it is. */
918	    @PostMapping("/claims/bulk-open")
919	    public BulkOpenService.Result bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
920	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
921	            @RequestBody @Valid BulkOpenRequest request) {
922	        return bulkOpen.open(sheetId.trim(), user.trim(), request.ids());
923	    }
924	
925	    /** Settle the selected claims in list order; each one that cannot be settled is left as it is. */
926	    @PostMapping("/claims/bulk-settle")
927	    public BulkSettleService.Result bulkSettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
928	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
929	            @RequestBody @Valid BulkSettleRequest request) {
930	        return bulkSettle.settle(sheetId.trim(), user.trim(), request.ids());
931	    }
932	
933	    /** Settle an OPEN claim; refused to the user who opened it; PENDING instead when a clerk settles it above the clerk limit. */
934	    @PostMapping("/claims/{id}/settle")
935	    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
936	            @PathVariable Long id,
937	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
938	        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.SETTLED));
939	    }
940	
941	    /** Re-settle a SETTLED claim at its figure as of today: a steward only. */
942	    @PostMapping("/claims/{id}/resettle")
943	    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
944	            @PathVariable Long id,
945	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
946	        return view(service.resettle(sheetId.trim(), user.trim(), id));
947	    }
948	
949	    /** A steward's reason for rejecting a PENDING claim. */
950	    public record RejectRequest(@NotBlank @Size(max = 1000) String reason) {
951	    }
952	
953	    /** Approve a PENDING claim: a steward only, and not the one who opened it. */
954	    @PostMapping("/claims/{id}/approve")
955	    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
956	            @PathVariable Long id,
957	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
958	        return view(service.approve(sheetId.trim(), user.trim(), id));
959	    }
960	
961	    /** Reject a PENDING claim with a reason, back to OPEN: a steward only. */
962	    @PostMapping("/claims/{id}/reject")
963	    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
964	            @PathVariable Long id,
965	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
966	            @RequestBody @Valid RejectRequest request) {
967	        // One line in the audit file: any run of white space in the reason becomes a single space.
968	        String reason = request.reason().trim().replaceAll("\\s+", " ");
969	        return view(service.reject(sheetId.trim(), user.trim(), id, reason));
970	    }
971	
972	    /** The person a claim is moved to. */
973	    public record ReassignRequest(@NotNull Long personId) {
974	    }
975	
976	    /** Move a DRAFT, OPEN or PENDING claim to another person: a role the permission matrix allows to reassign. */
977	    @PostMapping("/claims/{id}/reassign")
978	    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
979	            @PathVariable Long id,
980	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
981	            @RequestBody @Valid ReassignRequest request) {
982	        return view(service.reassign(sheetId.trim(), user.trim(), id, request.personId()));
983	    }
984	
985	    /** The date an OPEN claim is deferred until; it must be after the sheet's today. */
986	    public record DeferRequest(@NotNull LocalDate until) {
987	    }
988	
989	    /** Defer an OPEN claim until a date after the sheet's today. */
990	    @PostMapping("/claims/{id}/defer")
991	    public ClaimView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
992	            @PathVariable Long id,
993	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
994	            @RequestBody @Valid DeferRequest request) {
995	        return view(service.defer(sheetId.trim(), user.trim(), id, request.until()));
996	    }
997	
998	    /** Add a proof to a claim, raising its proofs count by one; refused for a SETTLED or VOID claim. */
999	    @PostMapping("/claims/{id}/proof")
1000	    public ClaimView addProof(@PathVariable @NotBlank @Size(max = 100) String sheetId,
1001	            @PathVariable Long id,
1002	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
1003	        return view(service.addProof(sheetId.trim(), user.trim(), id));
1004	    }
1005	
1006	    /** Void a DRAFT, OPEN or PENDING claim. */
1007	    @PostMapping("/claims/{id}/void")
1008	    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
1009	            @PathVariable Long id,
1010	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
1011	        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.VOID));
1012	    }
1013	
1014	    /** The claim as shown, with its status log. */
1015	    ClaimView view(Claim claim) {
1016	        return ClaimView.of(claim, service.logOf(claim));
1017	    }
1018	}
